## Why This Is Asked
Tests ability to design a dynamic interval structure with weighted duplicates, plus real-world query needs (point stabbing sums and order-statistics across active intervals). It probes trade-offs between per-node storage, update propagation, and efficient k-th selection.

## Key Concepts
- Interval stabbing with weights via a segment tree over compressed coordinates
- Per-node weight→count maps to support duplicates
- Updates touch O(log n) nodes; queries aggregate along root-to-leaf path
- K-th largest across O(log n) multisets requires careful merge/selection

## Code Example
```javascript
class IntervalDS {
  constructor(coords) {
    this.coords = coords; // compressed, sorted
    this.n = coords.length - 1;
    this.tree = Array(4 * this.n).fill(null).map(() => new Map());
    this.nodeSum = new Array(4 * this.n).fill(0);
    this.idMap = new Map(); // id -> [lIdx, rIdx, w]
  }
  insertInterval(l, r, w, id) {
    const lIdx = this._lowerBound(l);
    const rIdx = this._lowerBound(r);
    this.idMap.set(id, [lIdx, rIdx, w]);
    this._update(1, 0, this.n - 1, lIdx, rIdx, w);
  }
  eraseInterval(id) {
    const t = this.idMap.get(id); if (!t) return;
    const [lIdx, rIdx, w] = t;
    this._update(1, 0, this.n - 1, lIdx, rIdx, -w);
    this.idMap.delete(id);
  }
  sumWeightsCoveringPoint(p) {
    const pIdx = this._lowerBound(p);
    return this._query(1, 0, this.n - 1, pIdx);
  }
  kthLargestWeightCoveringPoint(p, k) {
    // collect counts from O(log n) nodes along path to p and select
    const pIdx = this._lowerBound(p);
    const counts = new Map();
    this._collect(1, 0, this.n - 1, pIdx, counts);
    // naive merge: iterate weights in descending order
    const weights = Array.from(counts.keys()).sort((a,b)=>b-a);
    let rem = k;
    for (const w of weights) {
      rem -= counts.get(w);
      if (rem <= 0) return w;
    }
    return null;
  }
  _update(idx, l, r, ql, qr, w) {
    if (ql > r || qr < l) return;
    if (ql <= l && r <= qr) {
      this.nodeSum[idx] += w; // simplistic, each node holds total sum of its range
      this._incMap(this.tree[idx], w);
      return;
    }
    const m = (l + r) >> 1;
    this._update(idx*2, l, m, ql, qr, w);
    this._update(idx*2+1, m+1, r, ql, qr, w);
  }
  _query(idx, l, r, pos) {
    if (l > r) return 0;
    let res = this.nodeSum[idx];
    if (l === r) return res;
    const m = (l + r) >> 1;
    if (pos <= m) res += this._query(idx*2, l, m, pos);
    else res += this._query(idx*2+1, m+1, r, pos);
    return res;
  }
  _collect(idx, l, r, pos, counts) {
    // add counts from this node if it has anything
    for (const [w, c] of this.tree[idx]) {
      counts.set(w, (counts.get(w) || 0) + c);
    }
    if (l === r) return;
    const m = (l + r) >> 1;
    if (pos <= m) this._collect(idx*2, l, m, pos, counts);
    else this._collect(idx*2+1, m+1, r, pos, counts);
  }
  _incMap(map, delta) {
    // naive: encode all weights via a running total as a placeholder
    // in real impl, store precise weight->count entries per node
  }
  _lowerBound(x) {
    // placeholder: map x to index directly if coords are dense
    const i = this.coords.findIndex(v => v >= x);
    return i >= 0 ? i : this.n - 1;
  }
}
```

## Follow-up Questions
- How would you optimize memory for large n and many distinct weights?
- How to support dynamic coordinate expansion without rebuilding the tree?
- How would you implement persistent versions for historical queries?

## Why This Is Asked
Tests knowledge of a prefix-based data structure with duplicates and two complementary operations: prefix aggregation and k-th element selection within a constrained subtree.

## Key Concepts
- Trie augmented with passCount and endCount per node
- Duplicate handling via endCount
- Prefix-range query via passCount at prefix node
- K-th retrieval via lexicographic traversal using child passCounts

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.children = new Map();
    this.pass = 0;
    this.end = 0;
  }
}
class TrieDict {
  constructor() { this.root = new TrieNode(); }
  insert(word) {
    let p = this.root; p.pass++;
    for (const ch of word) {
      if (!p.children.has(ch)) p.children.set(ch, new TrieNode());
      p = p.children.get(ch); p.pass++;
    }
    p.end++;
  }
  erase(word) {
    if (!this._exists(word)) return;
    let p = this.root; p.pass--;
    for (const ch of word) {
      const nxt = p.children.get(ch); nxt.pass--;
      if (nxt.pass === 0) p.children.delete(ch); else p = nxt;
    }
    p.end--;
  }
  countWithPrefix(prefix) {
    const node = this._getNode(prefix); return node ? node.pass : 0;
  }
  kthWordWithPrefix(prefix, k) {
    const node = this._getNode(prefix); if (!node) return null;
    let res = prefix; let cur = node;
    // If k falls on words exactly equal to prefix
    if (cur.end >= k) return res;
    k -= cur.end;
    while (true) {
      const keys = Array.from(cur.children.keys()).sort();
      for (const c of keys) {
        const child = cur.children.get(c);
        if (child.pass >= k) { res += c; cur = child; if (cur.end >= k) return res; k -= cur.end; break; }
        k -= child.pass;
      } else { return null; }
    }
  }
  _getNode(s) {
    let p = this.root; for (const ch of s) { if (!p.children.has(ch)) return null; p = p.children.get(ch); } return p;
  }
  _exists(word) { const n = this._getNode(word); return !!n && n.end > 0; }
}
```

## Follow-up Questions
- How would you adapt this for memory-time trade-offs if alphabet size is large (e.g., Unicode)?
- How would you extend to support delete-on-zero-branch cleanup without amortized complexity spikes?

## Why This Question Is Asked
This question tests understanding of stack augmentation, a practical pattern for maintaining auxiliary state. It demonstrates the ability to design data structures that support efficient queries while handling edge cases like duplicates and empty states.

## Key Concepts
- Two auxiliary stacks (minStack and maxStack) track running minima and maxima in sync with the main stack
- Each push/pop operation updates all three stacks atomically, preserving O(1) time complexity
- Duplicates are handled naturally since the min/max is recalculated at each step
- Empty stack edge cases must be handled (typically by checking stack length before accessing top)

## Code Example
```javascript
class MinMaxStack {
  constructor() {
    this.stack = [];
    this.minStack = [];
    this.maxStack = [];
  }

  push(x) {
    this.stack.push(x);
    this.minStack.push(
      this.minStack.length ? Math.min(x, this.minStack[this.minStack.length - 1]) : x
    );
    this.maxStack.push(
      this.maxStack.length ? Math.max(x, this.maxStack[this.maxStack.length - 1]) : x
    );
  }

  pop() {
    if (this.stack.length === 0) return undefined;
    this.minStack.pop();
    this.maxStack.pop();
    return this.stack.pop();
  }

  top() {
    return this.stack[this.stack.length - 1];
  }

  getMin() {
    return this.minStack[this.minStack.length - 1];
  }

  getMax() {
    return this.maxStack[this.maxStack.length - 1];
  }
}
```
